/* Firebase is the backend. Members submit requests; only an administrator can
   approve demo fulfilment. No client-side payment claim is trusted. */
(function(){
  'use strict';
  const v=window.ShopBusiness, assert=v.assert;
  let auth,db;
  const ref=(c,id)=>db.collection(c).doc(id);
  const rows=s=>s.docs.map(d=>({...d.data(),id:d.id}));
  const data=s=>s.exists?{...s.data(),id:s.id}:null;
  const all=async c=>rows(await db.collection(c).get());
  const own=async c=>rows(await db.collection(c).where('userId','==',auth.currentUser.uid).get());
  const requireUser=()=>{assert(auth.currentUser,'กรุณาเข้าสู่ระบบ');return auth.currentUser;};
  const paymentDefaults={bank:'ธนาคารตัวอย่าง DEMO',recipient:'INONGSHOP DEMO',account:'DEMO-ACCOUNT',instructions:'ใช้สำหรับสาธิตเท่านั้น ห้ามโอนเงินจริง',transfer:true,qr:true};
  async function me(){
    const u=requireUser(),[profile,role]=await Promise.all([ref('users',u.uid).get(),ref('admins',u.uid).get()]);
    const p=profile.exists?profile.data():{firstName:'',lastName:'',phone:'',wishlist:[],suspended:false};
    assert(!p.suspended,'บัญชีถูกระงับ กรุณาติดต่อผู้ดูแล');
    return {...p,id:u.uid,email:u.email,role:role.exists?'admin':'member'};
  }
  async function pricing(p){
    const items=v.cartItems(p.items),code=v.text(p.couponCode||'','คูปอง',30,true).toUpperCase();
    const products=await Promise.all(items.map(async i=>data(await ref('products',i.gameId).get())));
    const coupon=code?data(await ref('coupons',code).get()):null;
    assert(!code||coupon,'ไม่พบคูปอง');
    return {...v.quote(items,products.filter(Boolean),coupon),couponCode:code};
  }
  async function approve(orderId){
    // Queries only choose candidates. Every selected key and product is read
    // again inside the transaction before stock and ownership are written.
    const snapshot=data(await ref('orders',orderId).get());assert(snapshot,'ไม่พบคำสั่งซื้อ');
    const inventory=await all('key_inventory');
    return db.runTransaction(async tx=>{
      const o=data(await tx.get(ref('orders',orderId)));assert(o,'ไม่พบคำสั่งซื้อ');
      if(o.status==='paid')return o;
      assert(o.status==='awaiting_review','ลูกค้ายังไม่ได้ส่งคำขอยืนยัน');
      const buyer=data(await tx.get(ref('users',o.userId)));assert(buyer&&!buyer.suspended,'บัญชีผู้ซื้อถูกระงับ');
      const products=await Promise.all(o.items.map(i=>tx.get(ref('products',i.gameId)).then(data)));
      const coupon=o.couponCode?data(await tx.get(ref('coupons',o.couponCode))):null;
      assert(!o.couponCode||coupon,'ไม่พบคูปอง');
      const quote=v.quote(v.cartItems(o.items),products.filter(Boolean),coupon);
      assert(quote.totalCents===o.totalCents&&quote.subtotalCents===o.subtotalCents&&quote.discountCents===o.discountCents,'ราคา/ส่วนลดเปลี่ยนหรือยอดไม่ถูกต้อง กรุณายกเลิกและให้ลูกค้าสั่งใหม่');
      const selected=[];
      for(const i of quote.items){
        const candidates=inventory.filter(k=>k.gameId===i.gameId&&k.status==='available').slice(0,i.qty);
        assert(candidates.length===i.qty,'คีย์ไม่พอ กรุณาเติมสต็อก');
        for(const k of candidates){const fresh=data(await tx.get(ref('key_inventory',k.id)));assert(fresh?.status==='available'&&fresh.gameId===i.gameId,'คีย์ถูกใช้ไปแล้ว กรุณากดอนุมัติอีกครั้ง');selected.push({...fresh,gameName:i.name,platform:i.platform});}
      }
      const now=Date.now();
      for(const i of quote.items){
        tx.update(ref('products',i.gameId),{stock:products.find(p=>p.id===i.gameId).stock-i.qty});
        tx.set(ref('ownership',o.userId+'_'+i.gameId),{userId:o.userId,gameId:i.gameId,orderId,createdAt:now});
      }
      for(const k of selected){const sold={...k,userId:o.userId,orderId,status:'sold',soldAt:now};tx.set(ref('key_inventory',k.id),sold);tx.set(ref('user_keys',k.id),sold);}
      if(coupon)tx.update(ref('coupons',coupon.id),{usedCount:coupon.usedCount+1});
      const final={...quote,status:'paid',paidAt:now,approvedBy:auth.currentUser.uid};
      tx.update(ref('orders',orderId),final);return {...o,...final};
    });
  }
  const handlers={
    me:()=>me(),
    saveProfile:async p=>{
      const u=await me(),profile=v.profile(p),r=ref('users',u.id);
      await db.runTransaction(async tx=>{const s=await tx.get(r);if(s.exists)tx.update(r,profile);else tx.set(r,{...profile,email:u.email,wishlist:[],suspended:false,createdAt:Date.now()});});
      return {...u,...profile};
    },
    quoteOrder:p=>pricing(p),
    paymentSettings:async()=>({...paymentDefaults,...data(await ref('payment_settings','demo').get())}),
    savePaymentSettings:async p=>{const s={bank:v.text(p.bank,'ธนาคาร',80),recipient:v.text(p.recipient,'ผู้รับ',80),account:v.text(p.account,'บัญชีตัวอย่าง',60),instructions:v.text(p.instructions,'คำแนะนำ',500),transfer:p.transfer===true,qr:p.qr===true};assert(/^DEMO-[A-Z-]+$/.test(s.account),'ใช้รหัส DEMO- ตัวอักษรภาษาอังกฤษเท่านั้น ไม่ใช้เลขบัญชีจริง');assert(s.transfer||s.qr,'เปิดอย่างน้อยหนึ่งช่องทาง');await ref('payment_settings','demo').set(s);},
    createOrder:async p=>{
      const u=await me();assert(u.firstName,'กรุณาบันทึกข้อมูลสมาชิก');
      assert(/^[a-zA-Z0-9-]{1,100}$/.test(p.requestId),'รหัสคำขอไม่ถูกต้อง');
      const r=ref('orders',u.id+'_'+p.requestId),existing=await r.get();if(existing.exists)return data(existing);
      const quote=await pricing(p),now=Date.now();
      const o={...quote,...v.profile(p.buyer),userId:u.id,email:u.email,requestId:p.requestId,payment:'mock',status:'pending_payment',createdAt:now,expiresAt:now+1800000};
      return db.runTransaction(async tx=>{const old=await tx.get(r);if(old.exists)return data(old);tx.set(r,o);return {...o,id:r.id};});
    },
    confirmMockPayment:async p=>{
      const u=await me();return db.runTransaction(async tx=>{
        const r=ref('orders',p.orderId),o=data(await tx.get(r));assert(o&&o.userId===u.id,'ไม่พบคำสั่งซื้อของคุณ');
        if(['awaiting_review','paid'].includes(o.status))return o;
        assert(o.status==='pending_payment'&&o.expiresAt>Date.now(),'คำสั่งซื้อหมดอายุหรือถูกยกเลิก');
        const settings={...paymentDefaults,...data(await tx.get(ref('payment_settings','demo')))};
        assert(['transfer','qr'].includes(p.method)&&settings[p.method]===true,'กรุณาเลือกช่องทางที่เปิดใช้งาน');
        assert(p.slip==='DEMO-GENERATED'||(typeof p.slip==='string'&&p.slip.length<=280000&&/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(p.slip)),'แนบภาพ PNG/JPEG ไม่เกิน 200 KB หรือใช้สลิปตัวอย่าง');
        const paymentDetails={method:p.method,slip:p.slip,submittedAt:Date.now(),bank:settings.bank,recipient:settings.recipient,account:settings.account};
        tx.update(r,{status:'awaiting_review',paymentDetails});return {...o,status:'awaiting_review',paymentDetails};
      });
    },
    approveOrder:p=>approve(p.orderId),
    cancelOrder:async p=>{const u=await me();await db.runTransaction(async tx=>{const r=ref('orders',p.orderId),o=data(await tx.get(r));assert(o&&(o.userId===u.id||u.role==='admin')&&['pending_payment','awaiting_review'].includes(o.status),'ยกเลิกรายการนี้ไม่ได้');tx.update(r,{status:'cancelled'});});},
    myData:async()=>{const [orders,keys,reviews]=await Promise.all(['orders','user_keys','reviews'].map(own));return {orders:orders.sort((a,b)=>b.createdAt-a.createdAt),keys,reviews};},
    saveWishlist:async p=>{const u=await me();assert(Array.isArray(p.ids)&&p.ids.length<=100&&p.ids.every(x=>typeof x==='string'&&/^[\w-]{1,80}$/.test(x)),'รายการโปรดไม่ถูกต้อง');await ref('users',u.id).update({wishlist:[...new Set(p.ids)]});},
    saveReview:async p=>{const u=await me();assert(/^[\w-]{1,80}$/.test(p.gameId),'รหัสสินค้าไม่ถูกต้อง');await ref('reviews',u.id+'_'+p.gameId).set({userId:u.id,gameId:p.gameId,author:u.firstName,rating:v.integer(p.rating,'คะแนน',1,5),comment:v.text(p.comment,'รีวิว',1000),createdAt:Date.now()});},
    adminData:async()=>{const names=['products','key_inventory','orders','users','coupons','reviews'];const result=await Promise.all(names.map(all));return Object.fromEntries(names.map((n,i)=>[n,result[i]]));},
    saveProduct:async p=>{
      const r=p.id?ref('products',p.id):db.collection('products').doc();
      const price=v.money(p.price)/100,salePrice=p.salePrice==null?null:v.money(p.salePrice)/100;assert(salePrice===null||salePrice<=price,'ราคาลดต้องไม่เกินราคาปกติ');
      const product={name:v.text(p.name,'ชื่อเกม',120),genre:v.text(p.genre,'หมวดหมู่',80),platform:v.text(p.platform,'แพลตฟอร์ม',80),developer:v.text(p.developer||'','ผู้พัฒนา',100,true),desc:v.text(p.desc||'','รายละเอียด',3000,true),price,salePrice,images:[],active:p.active===true,updatedAt:Date.now()};
      const image=p.imageUrl===undefined?undefined:v.text(p.imageUrl,'ลิงก์รูป',2000,true);
      assert(image===undefined||image===''||/^https:\/\//i.test(image),'รูปปกต้องเป็นลิงก์ HTTPS');
      await db.runTransaction(async tx=>{const old=await tx.get(r);tx.set(r,{...product,images:image===undefined?(old.exists?old.data().images||[]:[]):image?[image]:[],stock:old.exists?old.data().stock:0,createdAt:old.exists?old.data().createdAt||Date.now():Date.now()},{merge:true});});return {id:r.id};
    },
    importKeys:async p=>{
      assert(Array.isArray(p.keys)&&p.keys.length>0&&p.keys.length<=100,'นำเข้าได้ 1–100 คีย์');
      const keys=p.keys.map(k=>v.text(k,'คีย์',120));assert(keys.every(k=>/^DEMO-[A-Z0-9-]+$/.test(k))&&new Set(keys).size===keys.length,'ต้องเป็นคีย์ DEMO- และไม่ซ้ำ');
      await db.runTransaction(async tx=>{const product=data(await tx.get(ref('products',p.gameId)));assert(product,'ไม่พบสินค้า');const old=await Promise.all(keys.map(k=>tx.get(ref('key_inventory',k))));assert(old.every(s=>!s.exists),'มีคีย์ซ้ำในระบบ');keys.forEach(key=>tx.set(ref('key_inventory',key),{key,gameId:p.gameId,status:'available',createdAt:Date.now()}));tx.update(ref('products',p.gameId),{stock:product.stock+keys.length});});
    },
    saveCoupon:async p=>{
      const code=v.text(p.code,'คูปอง',30).toUpperCase();assert(/^[A-Z0-9_-]+$/.test(code)&&['flat','percent'].includes(p.type),'คูปองไม่ถูกต้อง');
      const c={type:p.type,value:p.type==='percent'?v.integer(p.value,'ส่วนลด',1,100):v.money(p.value)/100,minPurchase:v.money(p.minPurchase)/100,maxUses:v.integer(p.maxUses,'จำนวนใช้',1,100000),active:p.active===true,expiresAt:p.expiresAt==null?null:v.integer(p.expiresAt,'วันหมดอายุ',1,8640000000000000)};
      await db.runTransaction(async tx=>{const r=ref('coupons',code),old=await tx.get(r),usedCount=old.exists?old.data().usedCount:0;assert(c.maxUses>=usedCount,'จำนวนสูงสุดต่ำกว่าที่ใช้ไปแล้ว');tx.set(r,{...c,usedCount});});
    },
    suspendUser:async p=>{assert(p.userId!==auth.currentUser.uid,'ระงับตัวเองไม่ได้');assert(!(await ref('admins',p.userId).get()).exists,'ระงับผู้ดูแลไม่ได้');await ref('users',p.userId).update({suspended:p.suspended===true});},
    deleteReview:p=>ref('reviews',p.id).delete(),
    seedDemo:async()=>{
      // Only add missing products. Existing stock, sales and keys are untouched.
      for(const p of window.SHOP_PRODUCTS){await db.runTransaction(async tx=>{const r=ref('products',p.id);if((await tx.get(r)).exists)return;tx.set(r,{...p,stock:5,active:true,createdAt:Date.now()});for(let n=1;n<=5;n++){const key=`DEMO-${p.id.toUpperCase()}-${String(n).padStart(4,'0')}`;tx.set(ref('key_inventory',key),{gameId:p.id,key,status:'available',createdAt:Date.now()});}});}
      for(const c of [{id:'SAVE10',type:'percent',value:10,minPurchase:500},{id:'KEYH50',type:'flat',value:50,minPurchase:0}])await db.runTransaction(async tx=>{const r=ref('coupons',c.id);if(!(await tx.get(r)).exists)tx.set(r,{...c,active:true,usedCount:0,maxUses:100,expiresAt:null});});
    }
  };
  const admins=new Set(['savePaymentSettings','approveOrder','adminData','saveProduct','importKeys','saveCoupon','suspendUser','deleteReview','seedDemo']);
  async function call(name,p={}){requireUser();assert(handlers[name],'ไม่พบคำสั่ง');if(admins.has(name))assert((await me()).role==='admin','เฉพาะผู้ดูแล');return await handlers[name](p)??{ok:true};}
  async function init(config){
    assert(window.firebase,'โหลด Firebase ไม่สำเร็จ กรุณาเชื่อมต่ออินเทอร์เน็ตแล้วเปิดใหม่');
    firebase.initializeApp(config);auth=firebase.auth();db=window.ShopFirestore('default');
    if(window.SHOP_EMULATOR){auth.useEmulator('http://127.0.0.1:9099',{disableWarnings:true});db.useEmulator('127.0.0.1',8080);}
    await new Promise(resolve=>{const off=auth.onAuthStateChanged(()=>{off();resolve();});});
    return {auth,db,fn:{httpsCallable:name=>async p=>({data:await call(name,p)})}};
  }
  window.FirebaseShop={init,call};
}());

'use strict';

const $ = (selector, root = document) => root.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const baht = cents => new Intl.NumberFormat('th-TH', {style:'currency', currency:'THB'}).format(cents/100);
const prefix = '';
let page = location.hash.slice(1) || 'home';
let auth, db, fn, user, products = [], admin = {}, currentTab = 'products', cartQuote = null, quoteVersion = 0;
let profileTab='overview', paymentSettings={}, paymentOrder=null;
const readLocal = (key, fallback) => {try{return JSON.parse(localStorage.getItem(key)) ?? fallback;}catch{return fallback;}};
const PRODUCT_CACHE='inongshop-products-v1', PRODUCT_CACHE_MS=120000;
const cachedProducts=readLocal(PRODUCT_CACHE,null);
let productLoadedAt=0;
if(cachedProducts&&Array.isArray(cachedProducts.items)&&Date.now()-cachedProducts.savedAt<PRODUCT_CACHE_MS){products=cachedProducts.items;productLoadedAt=cachedProducts.savedAt;}
const cartKey = () => `inongshop-cart-v2-${auth?.currentUser?.uid || 'guest'}`;
function cart() {
  const raw = readLocal(cartKey(), []);
  return Array.isArray(raw) ? raw.filter(i => i && typeof i.gameId === 'string' && Number.isInteger(i.qty) && i.qty > 0 && i.qty <= 10).slice(0,20) : [];
}
function saveCart(items) {localStorage.setItem(cartKey(), JSON.stringify(items)); $('#cart-count').textContent = items.reduce((n,i)=>n+i.qty,0);}
function flash(message) {$('#flash').textContent = message; clearTimeout(flash.timer); flash.timer = setTimeout(()=>$('#flash').textContent='',6000);}
const errorText = error => ({'auth/invalid-login-credentials':'อีเมลหรือรหัสผ่านไม่ถูกต้อง','auth/invalid-credential':'อีเมลหรือรหัสผ่านไม่ถูกต้อง','auth/wrong-password':'อีเมลหรือรหัสผ่านไม่ถูกต้อง','auth/user-not-found':'อีเมลหรือรหัสผ่านไม่ถูกต้อง','auth/email-already-in-use':'อีเมลนี้มีบัญชีแล้ว กรุณาเข้าสู่ระบบ','auth/weak-password':'รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร','auth/network-request-failed':'เชื่อมต่อไม่ได้ กรุณาตรวจสอบอินเทอร์เน็ต','auth/user-disabled':'บัญชีนี้ถูกระงับ','auth/too-many-requests':'ลองบ่อยเกินไป กรุณารอสักครู่','permission-denied':'Firebase ยังไม่อนุญาตการทำรายการนี้ กรุณาตรวจสิทธิ์และกฎฐานข้อมูล','auth/operation-not-allowed':'ต้องเปิด Email/Password ใน Firebase Authentication ก่อน','functions/unavailable':'Backend ยังไม่พร้อมใช้งาน'}[error.code] || error.message || 'เกิดข้อผิดพลาด');
async function api(name, data = {}) {return (await fn.httpsCallable(name)(data)).data;}
const button = (label, action, id='', extra='') => `<button class="btn btn-outline" type="button" data-action="${action}" data-id="${escape(id)}" ${extra}>${label}</button>`;
const field = (label, name, value='', type='text', extra='') => `<label class="field">${label}<input name="${name}" type="${type}" value="${escape(value)}" ${extra}></label>`;
const select = (label, name, options, value) => `<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${escape(v)}" ${String(v)===String(value)?'selected':''}>${escape(t)}</option>`).join('')}</select></label>`;
const textarea = (label, name, value='', extra='') => `<label class="field">${label}<textarea name="${name}" ${extra}>${escape(value)}</textarea></label>`;
const check = (label, name, value) => `<label class="inline-check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const submit = label => `<button class="btn btn-primary" type="submit">${label}</button>`;
const table = (heads, rows) => `<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}">ยังไม่มีข้อมูล</td></tr>`}</tbody></table></div>`;
const status = order => {const key = order.status==='pending_payment' && order.expiresAt<Date.now() ? 'expired' : order.status; return `<span class="status-pill status-${escape(key)}">${({awaiting_review:'รอผู้ดูแลอนุมัติ',pending_payment:'รอยืนยันคำขอ',paid:'ชำระแล้ว',cancelled:'ยกเลิก',expired:'หมดอายุ'})[key] || escape(key)}</span>`;};
const date = stamp => stamp ? new Date(stamp).toLocaleString('th-TH') : '—';
function showDialog(content) {const d=$('#dialog');d.innerHTML=`${button('ปิด','close-dialog')}<div class="panel">${content}</div>`;if(!d.open)d.showModal();}
function profileFields(p={}) {return field('ชื่อ','firstName',p.firstName,'text','required maxlength="80"')+field('นามสกุล','lastName',p.lastName,'text','required maxlength="80"')+field('เบอร์โทร','phone',p.phone,'tel','pattern="0[0-9]{9}" maxlength="10"');}
async function loadProducts(force=false) {
  if(!force&&products.length&&Date.now()-productLoadedAt<PRODUCT_CACHE_MS)return;
  const fresh=(await db.collection('products').where('active','==',true).get()).docs.map(d=>({id:d.id,...d.data()}));
  products=fresh;productLoadedAt=Date.now();
  try{localStorage.setItem(PRODUCT_CACHE,JSON.stringify({savedAt:productLoadedAt,items:fresh}));}catch{}
}
// Storefront presentation only. Authentication and purchase rules stay in the backend adapter.
function imageUrl(p) {
  const original=window.SHOP_PRODUCTS.find(x=>x.id===p.id);
  const url=p.images?.[0]||original?.images?.[0]||'';
  return /^https:\/\//i.test(url)?url:'assets/placeholder.svg';
}
function cards(list) {
  if(!list.length)return '<p class="empty">ไม่พบเกมที่ตรงกับตัวกรอง</p>';
  return `<div class="game-grid">${list.map(p=>{
    const sale=p.salePrice!=null&&p.salePrice<p.price;
    return `<article class="game-card"><div class="game-card-img"><button class="cover-link" type="button" data-action="detail" data-id="${escape(p.id)}" aria-label="รายละเอียด ${escape(p.name)}"><img src="${escape(imageUrl(p))}" alt="${escape(p.name)}" loading="lazy" decoding="async"></button>${sale?`<span class="game-badge badge-sale">ลด ${Math.round((1-p.salePrice/p.price)*100)}%</span>`:''}<button type="button" class="wish-button" data-action="wishlist" data-id="${escape(p.id)}" aria-label="รายการโปรด ${escape(p.name)}" aria-pressed="${(user?.wishlist||[]).includes(p.id)}">${(user?.wishlist||[]).includes(p.id)?'♥':'♡'}</button></div><div class="game-card-body"><div class="game-meta">${escape(p.platform)} · ${escape(p.genre)}</div><h3>${escape(p.name)}</h3><div class="game-price"><span class="current">${baht(Math.round((p.salePrice??p.price)*100))}</span>${sale?`<span class="original">${baht(Math.round(p.price*100))}</span>`:''}</div><p class="stock-label">คีย์ DEMO พร้อมส่ง ${p.stock} ชุด</p><div class="card-actions">${button('รายละเอียด','detail',p.id)}<button type="button" class="btn btn-primary" data-action="add-cart" data-id="${escape(p.id)}" ${p.stock<1?'disabled':''}>${p.stock<1?'สินค้าหมด':'ใส่ตะกร้า'}</button></div></div></article>`;
  }).join('')}</div>`;
}
function storeLink(params={}) {return '#store?'+new URLSearchParams(params).toString();}
function catalog() {
  const q=($('#search')?.value||'').toLowerCase(),genre=$('#genre')?.value||'',platform=$('#platform')?.value||'',sort=$('#sort')?.value||'';
  const min=$('#min-price')?.value,max=$('#max-price')?.value,sale=$('#sale-only')?.checked;
  let list=products.filter(p=>{
    const price=p.salePrice??p.price;
    return (p.name+' '+p.genre+' '+p.platform).toLowerCase().includes(q)&&(!genre||p.genre===genre)&&(!platform||p.platform.includes(platform))&&(!min||price>=Number(min))&&(!max||price<=Number(max))&&(!sale||p.salePrice!=null&&p.salePrice<p.price);
  });
  if(sort==='low')list.sort((a,b)=>(a.salePrice??a.price)-(b.salePrice??b.price));
  if(sort==='high')list.sort((a,b)=>(b.salePrice??b.price)-(a.salePrice??a.price));
  if(sort==='newest')list.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));
  $('#catalog').innerHTML=cards(list);$('#result-count').textContent=`พบ ${list.length} เกม`;
}
function renderStore() {
  if(page==='home'){renderHome();return;}
  const params=new URLSearchParams(location.hash.split('?')[1]||'');
  const genres=[...new Set(products.map(p=>p.genre))];
  $('#main').innerHTML=`<div class="store-layout"><aside class="filter-sidebar"><h2>ตัวกรอง</h2><div class="filter-group">${field('ค้นหาเกม','search','','search','id="search" placeholder="พิมพ์ชื่อเกม…"')}</div><div class="filter-group"><label class="field">แพลตฟอร์ม<select id="platform"><option value="">ทุกแพลตฟอร์ม</option>${['PC','PlayStation','Xbox','Nintendo'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><div class="filter-group"><label class="field">ประเภทเกม<select id="genre"><option value="">ทุกประเภท</option>${genres.map(g=>`<option value="${escape(g)}">${escape(g)}</option>`).join('')}</select></label></div><div class="filter-group"><h3>ช่วงราคา</h3><div class="price-range"><input id="min-price" type="number" min="0" aria-label="ราคาต่ำสุด" placeholder="ต่ำสุด"><span>–</span><input id="max-price" type="number" min="0" aria-label="ราคาสูงสุด" placeholder="สูงสุด"></div></div><label class="inline-check"><input id="sale-only" type="checkbox">เฉพาะเกมลดราคา</label><button class="btn btn-outline" id="clear-filters" type="button">ล้างตัวกรอง</button></aside><section class="store-results"><div class="store-heading"><div><p class="section-tag">GAME STORE</p><h1>เกมทั้งหมด</h1><p class="muted" id="result-count"></p></div><select id="sort" aria-label="เรียงลำดับ"><option value="">เรียงตามรายการ</option><option value="low">ราคาต่ำ → สูง</option><option value="high">ราคาสูง → ต่ำ</option><option value="newest">ใหม่ล่าสุด</option></select></div><div id="catalog"></div></section></div>`;
  for(const [id,key] of [['search','search'],['platform','platform'],['genre','genre'],['sort','sort']])$('#'+id).value=params.get(key)||'';
  $('#sale-only').checked=params.get('sale')==='1';
  for(const id of ['search','platform','genre','sort','min-price','max-price','sale-only'])$('#'+id).addEventListener('input',catalog);
  $('#clear-filters').addEventListener('click',()=>{for(const id of ['search','platform','genre','sort','min-price','max-price'])$('#'+id).value='';$('#sale-only').checked=false;catalog();});catalog();
}
function renderHome() {
  const slides=['https://images.unsplash.com/photo-1542751371-adc38448a05e?w=1200&q=65','https://images.unsplash.com/photo-1511512578047-dfb367046420?w=1200&q=65','https://images.unsplash.com/photo-1612287230202-1ff1d85d1bdf?w=1200&q=65'];
  const section=(tag,title,items,link)=>`<section class="section container"><div class="section-header"><div><div class="section-tag">${tag}</div><h2 class="section-title">${title}</h2></div><a class="section-link" href="${link}">ดูทั้งหมด →</a></div>${cards(items)}</section>`;
  $('#main').innerHTML=`<section class="hero" aria-label="แบนเนอร์ร้านเกม">${slides.map((url,i)=>`<div class="hero-slide ${i===0?'active':''}"><img class="hero-bg" src="${url}" alt="${['ห้องเล่นเกม','อุปกรณ์เล่นเกม','คอนโทรลเลอร์'][i]}" ${i?'loading="lazy"':''}></div>`).join('')}<div class="hero-overlay"></div><div class="hero-content"><div class="hero-tag">PREMIUM DIGITAL GAME STORE</div><h1>ซื้อเกมที่คุณต้องการ<br>ในราคาที่<span>คุ้มกว่า</span></h1><p>เลือกเกมโปรดจากหลากหลายแพลตฟอร์ม ทดลองสั่งซื้อและรับคีย์ DEMO ในคลังเกมส่วนตัวของคุณ</p><a href="#store" class="btn btn-primary">ดูเกมทั้งหมด →</a><div class="hero-stats"><div class="hero-stat"><div class="num">${products.length}</div><div class="lbl">เกมในร้าน</div></div><div class="hero-stat"><div class="num">${new Set(products.map(p=>p.platform)).size}</div><div class="lbl">แพลตฟอร์ม</div></div><div class="hero-stat"><div class="num">DEMO</div><div class="lbl">โปรเจกต์เพื่อการศึกษา</div></div></div></div><div class="slider-arrows"><button class="slider-arrow prev" type="button" aria-label="ภาพก่อนหน้า">‹</button><button class="slider-arrow next" type="button" aria-label="ภาพถัดไป">›</button></div><div class="dots">${slides.map((_,i)=>`<button class="dot ${i===0?'active':''}" type="button" aria-label="แบนเนอร์ภาพ ${i+1}" aria-pressed="${i===0}"></button>`).join('')}</div></section><div class="container"><form id="home-search" class="search-box"><div class="search-fields"><div class="search-field"><label for="home-query">ค้นหาเกม</label><input id="home-query" placeholder="พิมพ์ชื่อเกม ประเภท หรือแพลตฟอร์ม…"></div><div class="search-field"><label for="home-platform">แพลตฟอร์ม</label><select id="home-platform"><option value="">ทุกแพลตฟอร์ม</option>${['PC','PlayStation','Xbox','Nintendo'].map(x=>`<option>${x}</option>`).join('')}</select></div><button class="btn btn-primary" type="submit">ค้นหาเกม →</button></div></form><div class="features">${[['◇','เลือกเกมที่ใช่','รวมเกมจากหลายแพลตฟอร์ม'],['⚡','คลังเกมส่วนตัว','รับคีย์หลังผู้ดูแลอนุมัติ'],['✓','บัญชีออนไลน์','ข้อมูลเชื่อมต่อ Firebase'],['♡','รายการโปรด','เก็บเกมที่ชอบไว้ดูภายหลัง']].map(([icon,title,desc])=>`<div class="feature"><div class="feature-icon">${icon}</div><div><h3>${title}</h3><p>${desc}</p></div></div>`).join('')}</div></div>${section('เกมแนะนำ','เกมเด่นที่คัดสรรมาเพื่อคุณ',products.slice(0,4),'#store')}${section('โปรโมชั่น','เกมลดราคาสุดคุ้ม',products.filter(p=>p.salePrice!=null&&p.salePrice<p.price).slice(0,4),storeLink({sale:'1'}))}${section('เกมมาใหม่','เลือกเกมถัดไปของคุณ',[...products].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).slice(0,4),storeLink({sort:'newest'}))}<section class="section container"><div class="section-header"><div><div class="section-tag">หมวดหมู่</div><h2 class="section-title">เลือกจากหมวดหมู่ยอดนิยม</h2></div></div><div class="category-grid">${[...new Set(products.map(p=>p.genre))].slice(0,5).map(g=>`<a class="category-card" href="${escape(storeLink({genre:g}))}"><span class="category-symbol">✦</span><h3>${escape(g)}</h3><p>${products.filter(p=>p.genre===g).length} เกม</p></a>`).join('')}</div></section>`;
  $('.hero-bg')?.setAttribute('fetchpriority','high');
  $('#home-search').addEventListener('submit',e=>{e.preventDefault();navigate(storeLink({search:$('#home-query').value,platform:$('#home-platform').value})).catch(e=>flash(errorText(e)));});
  let slide=0;const show=i=>{slide=(i+slides.length)%slides.length;document.querySelectorAll('.hero-slide').forEach((el,n)=>el.classList.toggle('active',n===slide));document.querySelectorAll('.dot').forEach((el,n)=>{el.classList.toggle('active',n===slide);el.setAttribute('aria-pressed',String(n===slide));});};
  $('.slider-arrow.prev').addEventListener('click',()=>show(slide-1));$('.slider-arrow.next').addEventListener('click',()=>show(slide+1));document.querySelectorAll('.dot').forEach((el,i)=>el.addEventListener('click',()=>show(i)));
}

async function detail(id) {
  const p=products.find(p=>p.id===id);if(!p)return;
  const reviews=(await db.collection('reviews').where('gameId','==',id).get()).docs.map(d=>d.data());
  showDialog(`<h2>${escape(p.name)}</h2><img src="${escape(imageUrl(p))}" alt="${escape(p.name)}"><p>${escape(p.desc)}</p><p class="price">${baht(Math.round((p.salePrice??p.price)*100))}</p>${button('ใส่ตะกร้า','add-cart',id,p.stock<1?'disabled':'')}<h3>รีวิวจากผู้ซื้อ</h3>${reviews.map(r=>`<div class="order-box"><strong>${escape(r.author)} · ${r.rating}/5</strong><p>${escape(r.comment)}</p></div>`).join('')||'<p class="muted">ยังไม่มีรีวิว</p>'}`);
}
function renderAuth() {
  if(auth.currentUser&&user?.firstName){$('#main').innerHTML=`<section class="panel"><h1>เข้าสู่ระบบแล้ว</h1><p>${escape(user.email)}</p><div class="actions"><a class="btn btn-primary" href="#user">บัญชีของฉัน</a>${button('ออกจากระบบ','logout')}</div></section>`;return;}
  if(auth.currentUser){$('#main').innerHTML=`<section class="panel"><h2>กรอกข้อมูลสมาชิกให้ครบ</h2><p class="muted">บัญชีถูกสร้างแล้ว บันทึกข้อมูลด้านล่างเพื่อเริ่มใช้งาน</p><form data-form="profile">${profileFields(user)}${submit('บันทึกข้อมูล')}</form>${button('ออกจากระบบ','logout')}</section>`;return;}
  $('#main').innerHTML=`<div class="grid-two"><section class="panel"><h1>ยินดีต้อนรับกลับ</h1><form data-form="login">${field('อีเมล','email','','email','required autocomplete="email"')}${field('รหัสผ่าน','password','','password','required autocomplete="current-password"')}${submit('เข้าสู่ระบบ')}</form><details><summary>ลืมรหัสผ่าน</summary><form data-form="reset">${field('อีเมล','email','','email','required')}${submit('ส่งลิงก์รีเซ็ตรหัสผ่าน')}</form></details></section><section class="panel"><h2>สมัครสมาชิก</h2><form data-form="register">${profileFields()}${field('อีเมล','email','','email','required autocomplete="email"')}${field('รหัสผ่าน (อย่างน้อย 8 ตัวอักษร)','password','','password','required minlength="8" autocomplete="new-password"')}${field('ยืนยันรหัสผ่าน','confirm','','password','required minlength="8" autocomplete="new-password"')}${submit('สมัครสมาชิก')}</form></section></div>`;
  const layout=$('.grid-two');
  if(layout){
    layout.classList.add('auth-layout');
    layout.insertAdjacentHTML('afterbegin','<div class="auth-tabs" role="tablist" aria-label="สมาชิก"><button type="button" class="auth-tab active" role="tab" aria-selected="true" data-auth-tab="0">เข้าสู่ระบบ</button><button type="button" class="auth-tab" role="tab" aria-selected="false" data-auth-tab="1">สมัครสมาชิก</button></div>');
    const panels=[...layout.querySelectorAll('section.panel')];panels[1].hidden=true;
    layout.querySelectorAll('[data-auth-tab]').forEach(tab=>tab.addEventListener('click',()=>{const selected=Number(tab.dataset.authTab);panels.forEach((p,i)=>p.hidden=i!==selected);layout.querySelectorAll('[data-auth-tab]').forEach((t,i)=>{t.classList.toggle('active',i===selected);t.setAttribute('aria-selected',String(i===selected));});}));
  }
}
async function renderCart() {
  cartQuote=null;quoteVersion++;
  const items=cart();
  $('#main').innerHTML=`<h1>ตะกร้าสินค้า</h1><div class="panel">${table(['สินค้า','จำนวน','ราคาปัจจุบัน',''],items.map(i=>{const p=products.find(p=>p.id===i.gameId);return [escape(p?.name||'สินค้าปิดจำหน่าย'),`<input class="quantity" type="number" min="1" max="10" value="${i.qty}" data-qty="${escape(i.gameId)}" aria-label="จำนวน ${escape(p?.name)}">`,p?baht(Math.round((p.salePrice??p.price)*100)*i.qty):'—',button('ลบ','remove-cart',i.gameId)];}))}</div>${items.length?`<div class="grid-two"><section class="panel"><h2>ข้อมูลผู้ซื้อ</h2>${!user?'<p>กรุณาเข้าสู่ระบบก่อนสั่งซื้อ</p><a class="btn btn-primary" href="#auth">เข้าสู่ระบบ</a>':`<form id="checkout" data-form="checkout">${profileFields(user)}<label class="field">อีเมล<input value="${escape(user.email)}" disabled></label><p class="muted">ใช้ชำระเงินจำลอง ไม่มีการโอนเงินจริง</p>${submit('สร้างคำสั่งซื้อ')}</form>`}</section><section class="panel"><h2>สรุปรายการ</h2><form data-form="coupon">${field('รหัสคูปอง (เว้นว่างถ้าไม่ใช้)','couponCode',sessionStorage.getItem('couponCode')||'')}${submit('คำนวณยอด')}</form><div id="quote"></div></section></div>`:'<p class="empty">ตะกร้าว่าง <a href="#store">เลือกซื้อเกม</a></p>'}`;
  if(items.length&&user)await refreshQuote();
}
async function refreshQuote() {
  cartQuote=null;const version=++quoteVersion;const checkout=$('#checkout button[type=submit]');if(checkout)checkout.disabled=true;
  const el=$('#quote');if(!el)return;
  el.textContent='กำลังตรวจราคาและสต็อก…';
  try {
    const result=await api('quoteOrder',{items:cart(),couponCode:sessionStorage.getItem('couponCode')||''});
    if(version!==quoteVersion)return;
    cartQuote=result;el.innerHTML=`<div class="summary-line"><span>ราคาสินค้า</span><span>${baht(result.subtotalCents)}</span></div><div class="summary-line"><span>ส่วนลด</span><span>−${baht(result.discountCents)}</span></div><div class="summary-line price"><span>ยอดรวม</span><span>${baht(result.totalCents)}</span></div><p class="muted">ตรวจสต็อกอีกครั้งเมื่อยืนยันชำระเงิน</p>`;
    if(checkout)checkout.disabled=false;
  }catch(e){if(version===quoteVersion)el.innerHTML=`<p class="error-box">${escape(errorText(e))}</p>`;}
}
function orderMarkup(o, allowPay=true) {
  const pending=o.status==='pending_payment'&&o.expiresAt>Date.now();
  return `<article class="order-box"><h3>#${escape(o.id.slice(-8))} ${status(o)}</h3><p class="muted">${date(o.createdAt)} · ${escape(o.email)}</p>${o.items.map(i=>`<p>${escape(i.name)} × ${i.qty}</p>`).join('')}<p class="price">${baht(o.totalCents)}</p>${o.paymentDetails?`<p>ช่องทาง: ${o.paymentDetails.method==='qr'?'สแกน QR จำลอง':'โอนเงินจำลอง'} · ส่งเมื่อ ${date(o.paymentDetails.submittedAt)}</p>`:''}<div class="actions">${o.paymentDetails||o.status==='paid'?button(o.status==='paid'?'ใบเสร็จจำลอง':'ดูหลักฐานจำลอง','payment-proof',o.id):''}${!allowPay&&o.status==='awaiting_review'?button('อนุมัติและส่งคีย์ DEMO','approve',o.id):''}${pending&&allowPay?button('ไปชำระเงินจำลอง','pay',o.id):''}${['pending_payment','awaiting_review'].includes(o.status)?button(!allowPay&&o.status==='awaiting_review'?'ไม่อนุมัติ / ยกเลิก':'ยกเลิกคำสั่งซื้อ','cancel-order',o.id):''}</div></article>`;
}
async function renderUser() {
  const data=await api('myData');
  $('#main').innerHTML=`<h1>บัญชีของฉัน</h1>${button('โหลดคำสั่งซื้อ / คีย์ล่าสุด','refresh-user')}<p>${escape(user?.firstName||'สมาชิก')} · ${escape(user?.email)}</p><div class="actions">${user.role==='admin'?'<a class="btn btn-primary" href="#admin">จัดการหลังบ้าน</a>':''}${button('ออกจากระบบ','logout')}</div><div class="grid-two"><section class="panel"><h2>ข้อมูลส่วนตัว</h2><form data-form="profile">${profileFields(user)}${submit('บันทึกข้อมูล')}</form></section><section class="panel"><h2>เปลี่ยนรหัสผ่าน</h2><form data-form="password">${field('รหัสผ่านเดิม','old','','password','required autocomplete="current-password"')}${field('รหัสผ่านใหม่','password','','password','required minlength="8" autocomplete="new-password"')}${field('ยืนยันรหัสผ่านใหม่','confirm','','password','required minlength="8" autocomplete="new-password"')}${submit('เปลี่ยนรหัสผ่าน')}</form></section></div><section class="panel" id="orders"><h2>คำสั่งซื้อ</h2>${data.orders.map(o=>orderMarkup(o)).join('')||'<p class="muted">ยังไม่มีคำสั่งซื้อ</p>'}</section><section class="panel" id="library"><h2>คลังเกมของฉัน</h2><p class="muted">คีย์ตัวอย่างสำหรับสาธิต ใช้เปิดเกมจริงไม่ได้</p>${data.keys.map(k=>`<div class="order-box"><h3>${escape(k.gameName)}</h3><code class="key-code">${escape(k.key)}</code><div class="actions">${button('คัดลอก','copy',k.key)}${button('เขียนรีวิว','review',k.gameId)}</div></div>`).join('')||'<p>ยังไม่มีคีย์</p>'}</section><section class="panel"><h2>รายการโปรด</h2>${cards(products.filter(p=>(user.wishlist||[]).includes(p.id)))}</section>`;
}
function renderAdminTab() {
  $('#admin-tabs').innerHTML=[['products','สินค้า'],['key_inventory','คีย์เกม'],['orders','คำสั่งซื้อ / ตรวจชำระ'],['users','สมาชิก'],['coupons','คูปอง'],['reviews','รีวิว'],['payment','ตั้งค่าชำระเงิน']].map(([id,label])=>button(label,'admin-tab',id,`aria-pressed="${id===currentTab}"`)).join('');
  const content=$('#admin-content');
  if(currentTab==='products') content.innerHTML=button('เพิ่มสินค้า','edit-product')+button('เพิ่มชุดสินค้าสาธิต','seed-demo')+table(['สินค้า','ราคา','คีย์พร้อมขาย','สถานะ','จัดการ'],admin.products.map(p=>[escape(p.name),baht(Math.round((p.salePrice??p.price)*100)),p.stock,p.active?'เปิดขาย':'ปิดขาย',button('แก้ไข / ปิดขาย','edit-product',p.id)]));
  if(currentTab==='key_inventory') content.innerHTML=button('นำเข้าคีย์ตัวอย่าง','import-keys')+table(['เกม','คีย์','สถานะ'],admin.key_inventory.map(k=>[escape(admin.products.find(p=>p.id===k.gameId)?.name||k.gameId),`<code>${escape(k.key)}</code>`,k.status==='sold'?'ขายแล้ว':'พร้อมขาย']));
  if(currentTab==='orders') content.innerHTML=admin.orders.sort((a,b)=>b.createdAt-a.createdAt).map(o=>orderMarkup(o,false)).join('')||'<p>ยังไม่มีคำสั่งซื้อ</p>';
  if(currentTab==='users') content.innerHTML=table(['ชื่อ','อีเมล','สถานะ','จัดการ'],admin.users.map(u=>[escape((u.firstName||'')+' '+(u.lastName||'')),escape(u.email),u.suspended?'ระงับ':'ใช้งาน',button(u.suspended?'เปิดใช้งาน':'ระงับบัญชี','suspend',u.id)]));
  if(currentTab==='coupons') content.innerHTML=button('เพิ่มคูปอง','edit-coupon')+table(['รหัส','ส่วนลด','ใช้ไป/สูงสุด','สถานะ',''],admin.coupons.map(c=>[escape(c.id),c.type==='percent'?`${c.value}%`:baht(c.value*100),`${c.usedCount}/${c.maxUses}`,c.active?'เปิด':'ปิด',button('แก้ไข','edit-coupon',c.id)]));
  if(currentTab==='reviews') content.innerHTML=table(['ผู้รีวิว','เกม','คะแนน','ข้อความ',''],admin.reviews.map(r=>[escape(r.author),escape(admin.products.find(p=>p.id===r.gameId)?.name||r.gameId),r.rating,escape(r.comment),button('ลบรีวิว','delete-review',r.id)]));
  if(currentTab==='payment') content.innerHTML=`<h2>ช่องทางชำระเงินจำลอง</h2><p class="demo-banner">ไม่มีการรับเงินจริง ไม่มีบัตร และไม่มี QR สำหรับโอนเงินจริง</p><form data-form="payment-settings">${field('ชื่อธนาคารตัวอย่าง','bank',paymentSettings.bank,'text','required maxlength="80"')}${field('ชื่อผู้รับตัวอย่าง','recipient',paymentSettings.recipient,'text','required maxlength="80"')}${field('รหัสบัญชีตัวอย่าง (DEMO- และตัวอักษรเท่านั้น)','account',paymentSettings.account,'text','required pattern="DEMO-[A-Z-]+" maxlength="60"')}${textarea('คำแนะนำ','instructions',paymentSettings.instructions,'required maxlength="500"')}${check('เปิดโอนเงินจำลอง','transfer',paymentSettings.transfer)}${check('เปิดสแกน QR จำลอง','qr',paymentSettings.qr)}${submit('บันทึกช่องทางชำระเงิน')}</form>`;
  else content.insertAdjacentHTML('afterbegin',`<label class="field">ค้นหาในหน้านี้<input type="search" data-panel-search placeholder="ชื่อ รหัส อีเมล หรือสถานะ" aria-label="ค้นหาในหลังบ้าน"></label>`);
}
